import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import './ProjectManagementPage.css';

const ProjectManagementPage = ({ user }) => {
  const { projectId } = useParams();
  const navigate = useNavigate();
  const [project, setProject] = useState(null);
  const [currentFolder, setCurrentFolder] = useState(null);
  const [folders, setFolders] = useState([]);
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [showCreateFolder, setShowCreateFolder] = useState(false);
  const [newFolderName, setNewFolderName] = useState('');
  const [selectedItems, setSelectedItems] = useState([]);
  const [showUpload, setShowUpload] = useState(false);
  const [dragOver, setDragOver] = useState(false);

  useEffect(() => {
    if (user) {
      fetchProject();
    }
  }, [projectId, user]);

  const fetchProject = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('access_token');
      const response = await axios.get(`/api/projects/${projectId}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      setProject(response.data);
      await fetchProjectContents();
    } catch (error) {
      console.error('Error fetching project:', error);
      setError('Проект не найден или нет прав доступа');
    } finally {
      setLoading(false);
    }
  };

  const fetchProjectContents = async (folderId = null) => {
    try {
      const token = localStorage.getItem('access_token');
      const [foldersResponse, filesResponse] = await Promise.all([
        axios.get(`/api/projects/${projectId}/folders`, {
          headers: { 'Authorization': `Bearer ${token}` },
          params: { parent_id: folderId }
        }),
        axios.get(`/api/projects/${projectId}/files`, {
          headers: { 'Authorization': `Bearer ${token}` },
          params: { folder_id: folderId }
        })
      ]);
      setFolders(foldersResponse.data);
      setFiles(filesResponse.data);
    } catch (error) {
      console.error('Error fetching project contents:', error);
      setError('Ошибка загрузки содержимого проекта');
    }
  };

  const handleCreateFolder = async (e) => {
    e.preventDefault();
    if (!newFolderName.trim()) return;

    try {
      const token = localStorage.getItem('access_token');
      await axios.post(`/api/projects/${projectId}/folders`, {
        name: newFolderName.trim(),
        parent_id: currentFolder?.id || null
      }, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      
      setSuccess('Папка создана');
      setNewFolderName('');
      setShowCreateFolder(false);
      await fetchProjectContents(currentFolder?.id || null);
    } catch (error) {
      setError(error.response?.data?.detail || 'Ошибка создания папки');
    }
  };

  const handleFileUpload = async (file) => {
    // Проверяем тип файла
    const allowedTypes = ['image/png', 'image/jpeg', 'image/webp', 'image/gif', 'text/css', 'text/html', 'application/javascript'];
    const allowedExtensions = ['.png', '.jpg', '.jpeg', '.webp', '.gif', '.css', '.html', '.js'];
    const fileExtension = '.' + file.name.split('.').pop().toLowerCase();
    
    if (!allowedTypes.includes(file.type) && !allowedExtensions.includes(fileExtension)) {
      setError('Недопустимый тип файла. Разрешены: PNG, JPEG, WebP, GIF, CSS, HTML, JS');
      return;
    }

    // Проверяем размер файла (10MB)
    if (file.size > 10 * 1024 * 1024) {
      setError('Файл слишком большой. Максимальный размер: 10MB');
      return;
    }

    try {
      const token = localStorage.getItem('access_token');
      const formData = new FormData();
      formData.append('file', file);
      formData.append('folder_id', currentFolder?.id || null);

      await axios.post(`/api/projects/${projectId}/files`, formData, {
        headers: { 
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'multipart/form-data'
        }
      });
      
      setSuccess('Файл загружен');
      await fetchProjectContents(currentFolder?.id || null);
    } catch (error) {
      setError(error.response?.data?.detail || 'Ошибка загрузки файла');
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setDragOver(false);
    
    const files = Array.from(e.dataTransfer.files);
    files.forEach(file => handleFileUpload(file));
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    setDragOver(true);
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    setDragOver(false);
  };

  const handleDownloadFile = async (file) => {
    try {
      const token = localStorage.getItem('access_token');
      const response = await axios.get(`/api/projects/${projectId}/files/${file.id}/download`, {
        headers: { 'Authorization': `Bearer ${token}` },
        responseType: 'blob'
      });
      
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', file.original_filename);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      setError('Ошибка скачивания файла');
    }
  };

  const handleDeleteItem = async (item, type) => {
    if (!window.confirm(`Вы уверены, что хотите удалить ${type === 'folder' ? 'папку' : 'файл'} "${item.name || item.original_filename}"?`)) {
      return;
    }

    try {
      const token = localStorage.getItem('access_token');
      if (type === 'folder') {
        await axios.delete(`/api/projects/${projectId}/folders/${item.id}`, {
          headers: { 'Authorization': `Bearer ${token}` }
        });
      } else {
        await axios.delete(`/api/projects/${projectId}/files/${item.id}`, {
          headers: { 'Authorization': `Bearer ${token}` }
        });
      }
      
      setSuccess(`${type === 'folder' ? 'Папка' : 'Файл'} удален`);
      await fetchProjectContents(currentFolder?.id || null);
    } catch (error) {
      setError(error.response?.data?.detail || `Ошибка удаления ${type === 'folder' ? 'папки' : 'файла'}`);
    }
  };

  const handleFolderClick = (folder) => {
    setCurrentFolder(folder);
    fetchProjectContents(folder.id);
  };

  const handleBackClick = () => {
    if (currentFolder?.parent_id) {
      // Переходим к родительской папке
      fetchProjectContents(currentFolder.parent_id);
    } else {
      // Возвращаемся к корневой папке
      setCurrentFolder(null);
      fetchProjectContents();
    }
  };

  const getFileIcon = (file) => {
    const extension = file.original_filename.split('.').pop().toLowerCase();
    switch (extension) {
      case 'png':
      case 'jpg':
      case 'jpeg':
      case 'webp':
      case 'gif':
        return '🖼️';
      case 'css':
        return '🎨';
      case 'html':
        return '🌐';
      case 'js':
        return '📜';
      default:
        return '📄';
    }
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  if (loading) {
    return (
      <div className="project-management-page">
        <div className="loading">Загрузка проекта...</div>
      </div>
    );
  }

  if (error && !project) {
    return (
      <div className="project-management-page">
        <div className="error">
          <h2>Ошибка</h2>
          <p>{error}</p>
          <button className="btn btn-primary" onClick={() => navigate('/settings')}>
            Вернуться к настройкам
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="project-management-page">
      <div className="project-header">
        <div className="project-info">
          <button className="back-btn" onClick={() => navigate('/settings')}>
            ← Настройки
          </button>
          <h1>{project?.title}</h1>
          {currentFolder && (
            <div className="breadcrumb">
              <span>Корневая папка</span>
              <span>›</span>
              <span>{currentFolder.name}</span>
            </div>
          )}
        </div>
        <div className="project-actions">
          <button 
            className="btn btn-primary"
            onClick={() => setShowCreateFolder(true)}
          >
            📁 Создать папку
          </button>
          <button 
            className="btn btn-secondary"
            onClick={() => setShowUpload(!showUpload)}
          >
            📤 Загрузить файлы
          </button>
        </div>
      </div>

      {error && <div className="alert alert-error">{error}</div>}
      {success && <div className="alert alert-success">{success}</div>}

      {showCreateFolder && (
        <div className="modal-overlay">
          <div className="modal">
            <h3>Создать папку</h3>
            <form onSubmit={handleCreateFolder}>
              <input
                type="text"
                value={newFolderName}
                onChange={(e) => setNewFolderName(e.target.value)}
                placeholder="Название папки"
                required
                autoFocus
              />
              <div className="modal-actions">
                <button type="submit" className="btn btn-primary">Создать</button>
                <button 
                  type="button" 
                  className="btn btn-secondary"
                  onClick={() => {
                    setShowCreateFolder(false);
                    setNewFolderName('');
                  }}
                >
                  Отмена
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div 
        className={`file-manager ${dragOver ? 'drag-over' : ''}`}
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
      >
        {showUpload && (
          <div className="upload-area">
            <input
              type="file"
              id="file-upload"
              multiple
              accept=".png,.jpg,.jpeg,.webp,.gif,.css,.html,.js"
              onChange={(e) => {
                Array.from(e.target.files).forEach(file => handleFileUpload(file));
                e.target.value = '';
              }}
              style={{ display: 'none' }}
            />
            <label htmlFor="file-upload" className="upload-btn">
              📤 Выберите файлы для загрузки
            </label>
            <p>Или перетащите файлы сюда</p>
            <p className="upload-info">
              Разрешены: PNG, JPEG, WebP, GIF, CSS, HTML, JS (макс. 10MB каждый)
            </p>
          </div>
        )}

        <div className="file-grid">
          {/* Кнопка "Назад" если мы не в корневой папке */}
          {currentFolder && (
            <div className="file-item folder-item" onClick={handleBackClick}>
              <div className="file-icon">📁</div>
              <div className="file-name">..</div>
              <div className="file-type">Назад</div>
            </div>
          )}

          {/* Папки */}
          {folders.map((folder) => (
            <div key={folder.id} className="file-item folder-item" onClick={() => handleFolderClick(folder)}>
              <div className="file-icon">📁</div>
              <div className="file-name">{folder.name}</div>
              <div className="file-type">Папка</div>
              <div className="file-actions">
                <button 
                  className="btn btn-danger btn-sm"
                  onClick={(e) => {
                    e.stopPropagation();
                    handleDeleteItem(folder, 'folder');
                  }}
                >
                  🗑️
                </button>
              </div>
            </div>
          ))}

          {/* Файлы */}
          {files.map((file) => (
            <div key={file.id} className="file-item">
              <div className="file-icon">{getFileIcon(file)}</div>
              <div className="file-name">{file.original_filename}</div>
              <div className="file-size">{formatFileSize(file.file_size)}</div>
              <div className="file-type">{file.content_type}</div>
              <div className="file-actions">
                <button 
                  className="btn btn-primary btn-sm"
                  onClick={() => handleDownloadFile(file)}
                >
                  ⬇️
                </button>
                <button 
                  className="btn btn-danger btn-sm"
                  onClick={() => handleDeleteItem(file, 'file')}
                >
                  🗑️
                </button>
              </div>
            </div>
          ))}

          {/* Пустое состояние */}
          {folders.length === 0 && files.length === 0 && !currentFolder && (
            <div className="empty-state">
              <div className="empty-icon">📁</div>
              <h3>Папка пуста</h3>
              <p>Создайте папку или загрузите файлы</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProjectManagementPage;
